# Perform migration actions on Spotify: add song library, album library, and create playlists and add tracks.
# We'll (re)login to Spotify, re-parse backup, and reuse song_id_map/album_id_map/playlists if present; otherwise recompute mapping.

import re
from collections import defaultdict

# --- Helper functions ---
def norm(s):
    return re.sub(r'\s+', ' ', (s or '').strip().lower())

def parse_artists_str(artists_str):
    parts = [p.strip() for p in (artists_str or '').split(',')]
    return [p for p in parts if p]

def song_key(title, artists_list):
    return (norm(title), tuple(sorted(norm(a) for a in artists_list)))

def album_key(title, artists_list):
    return (norm(title), tuple(sorted(norm(a) for a in artists_list)))

# --- Login Spotify ---
spotify_pw = [p['password'] for p in apis.supervisor.show_account_passwords() if p['account_name']=='spotify'][0]
spotify_login = apis.spotify.login(username='ka_burt@gmail.com', password=spotify_pw)
access_token = spotify_login['access_token']
print('spotify_access_token_prefix', access_token[:12])

# --- Load and parse backup file ---
fs_pw = [p['password'] for p in apis.supervisor.show_account_passwords() if p['account_name']=='file_system'][0]
fs_token = apis.file_system.login(username='ka_burt@gmail.com', password=fs_pw)['access_token']
content = apis.file_system.show_file(file_path='~/backups/music.txt', access_token=fs_token)['content']

lines = [ln.rstrip('\n') for ln in content.splitlines()]
section = None
songs = []
albums = []
playlists = defaultdict(list)
current_playlist = None

for ln in lines:
    if not ln.strip():
        continue
    if ln.startswith('# Song Library'):
        section = 'songs'
        continue
    if ln.startswith('# Album Library'):
        section = 'albums'
        continue
    if ln.startswith('# Playlists'):
        section = 'playlists'
        current_playlist = None
        continue

    if section == 'songs':
        if ln.startswith('- '):
            item = ln[2:]
            if ' by ' in item:
                title, artist_part = item.split(' by ', 1)
                songs.append({'title': title.strip(), 'artists_str': artist_part.strip()})
        continue

    if section == 'albums':
        if ln.startswith('- '):
            item = ln[2:]
            if ' by ' in item:
                title, artist_part = item.split(' by ', 1)
                albums.append({'title': title.strip(), 'artists_str': artist_part.strip()})
        continue

    if section == 'playlists':
        if ln.startswith('## '):
            current_playlist = ln[3:].strip()
            continue
        if ln.startswith('- ') and current_playlist:
            item = ln[2:]
            if ' by ' in item:
                title, artist_part = item.split(' by ', 1)
                playlists[current_playlist].append({'title': title.strip(), 'artists_str': artist_part.strip()})
        continue

print('backup_parsed_counts', {'songs': len(songs), 'albums': len(albums), 'playlists': len(playlists)})

