# Unique song items referenced anywhere (song library + playlist tracks)
unique_song_items = []
seen = set()
for item in songs:
    alist = parse_artists_str(item['artists_str'])
    k = song_key(item['title'], alist)
    if k not in seen:
        seen.add(k)
        unique_song_items.append({'title': item['title'], 'artists_list': alist, 'key': k})
for plist_items in playlists.values():
    for item in plist_items:
        alist = parse_artists_str(item['artists_str'])
        k = song_key(item['title'], alist)
        if k not in seen:
            seen.add(k)
            unique_song_items.append({'title': item['title'], 'artists_list': alist, 'key': k})

print('unique_song_items_to_map', len(unique_song_items))

# Search exact songs by title only, then exact post-filter on artist set.

def search_exact_song_id(title, artists_list):
    expected_artists = set(norm(a) for a in artists_list)
    results = []
    page_index = 0
    while True:
        page = apis.spotify.search_songs(query=title, page_index=page_index, page_limit=20)
        if not page:
            break
        results.extend(page)
        page_index += 1
        if page_index > 100:
            break
    matches = []
    for r in results:
        if norm(r.get('title','')) != norm(title):
            continue
        api_artists = set(norm(a.get('name','')) for a in r.get('artists', []))
        if api_artists == expected_artists:
            matches.append(r)
    return matches

song_id_map = {}
missing_song = []
for item in unique_song_items:
    matches = search_exact_song_id(item['title'], item['artists_list'])
    if len(matches)==1:
        song_id_map[item['key']] = matches[0]['song_id']
    else:
        missing_song.append({'title': item['title'], 'artists': item['artists_list'], 'match_count': len(matches)})

print('song_id_map_count', len(song_id_map))
print('missing_song_count', len(missing_song))
if missing_song:
